from __future__ import annotations

import re
from typing import Any

from .cue_text import (
    _CLAUSE_BREAK,
    _MAX_CJK_CHARS,
    _MAX_CUE_DURATION_S,
    _display_len,
    _is_cjk_heavy,
    _singing_lyric_len,
)

_COLLAPSE_CPS = 40.0


_COLLAPSE_MIN_CHARS = 8


_DEFAULT_CHUNK_SPAN_S = 30.0


_REPAIR_TARGET_CPS_JA = 9.0


_REPAIR_TARGET_CPS_LATIN = 14.0


_REPAIR_MIN_CPS = 20.0


_REPAIR_MAX_EXPAND_S = 24.0


_REPAIR_PART_GAP_S = 0.08


_REPAIR_RUN_GAP_S = 0.12


_SINGING_TARGET_CPS_CJK = 1.5


_SINGING_TARGET_CPS_LATIN = 5.0


_SINGING_MAX_CUE_S = 9.0


_SINGING_NEIGHBOR_GAP_S = 0.06


_SINGING_MIN_HOLD_S = 4.2


_SINGING_MERGE_GAP_S = 1.25


_SINGING_MERGE_GAP_SHORT_S = 5.5


_SINGING_MERGE_MAX_S = 9.0


_SINGING_MERGE_MAX_CHARS = 12


_SINGING_MERGE_SHORT_CHARS = 7


_SINGING_MERGE_COMPLETE_CHARS = 6


_SINGING_FILLER_RE = re.compile(
    r"^(嗯+|哦+|啊+|噢+|唔+|嘿+|呵+|哼+|woo+|whoa+|oh+|ah+|ooh+|home|you|yeah|hey)[\s。．\.!?！？…]*$",
    re.IGNORECASE,
)


def merge_cues_for_singing(
    cues: list[dict[str, Any]] | None,
    *,
    max_gap_s: float = _SINGING_MERGE_GAP_S,
    max_gap_short_s: float = _SINGING_MERGE_GAP_SHORT_S,
    max_merged_s: float = _SINGING_MERGE_MAX_S,
    max_chars: int = _SINGING_MERGE_MAX_CHARS,
    short_chars: int = _SINGING_MERGE_SHORT_CHARS,
    complete_chars: int = _SINGING_MERGE_COMPLETE_CHARS,
) -> list[dict[str, Any]]:
    """Merge near-adjacent short cues into XLSub-sized karaoke lines.

    Reference Cantonese MV karaoke keeps ~8–11 CJK chars / ~4–7s per line.
    Glue short FireRed islands; do not paste two already-complete lines together.
    Half-lines (both < ``short_chars``) may bridge a wider gap (e.g. 奉献+斗争).
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    gap_lim = max(0.05, float(max_gap_s))
    gap_short = max(gap_lim, float(max_gap_short_s))
    dur_cap = max(2.0, float(max_merged_s))
    char_cap = max(8, int(max_chars))
    short_cap = max(4, int(short_chars))
    complete_cap = max(4, int(complete_chars))
    out: list[dict[str, Any]] = []
    buf = dict(ordered[0])
    buf_text = str(buf.get("text") or "").strip()
    for cue in ordered[1:]:
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        b_start = float(buf.get("start") or 0)
        b_end = float(buf.get("end") or b_start)
        gap = start - b_end
        merged_dur = end - b_start
        left_n = _singing_lyric_len(buf_text)
        right_n = _singing_lyric_len(text)
        merged_chars = left_n + right_n
        both_short = left_n < short_cap and right_n < short_cap
        gap_ok = gap <= (gap_short if both_short else gap_lim)
        # Refuse gluing two already-complete lyric lines (incl. 6-char XLSub lines).
        both_complete = left_n >= complete_cap and right_n >= complete_cap
        can = (
            gap_ok
            and merged_dur <= dur_cap
            and merged_chars <= char_cap
            and not both_complete
        )
        if can:
            # Karaoke ZH lines: never insert ASCII spaces between CJK phrases.
            if buf_text and text:
                left = buf_text.rstrip("，,、。．.！!？?；;：:… ")
                right = text.lstrip("，,、。．.！!？?；;：:… ")
                if _is_cjk_heavy(left) and _is_cjk_heavy(right):
                    buf_text = f"{left}{right}"
                else:
                    buf_text = f"{left} {right}".strip()
            else:
                buf_text = buf_text or text
            buf["end"] = max(b_end, end)
            buf["text"] = buf_text
            continue
        buf["text"] = buf_text
        out.append(buf)
        buf = dict(cue)
        buf_text = text
    buf["text"] = buf_text
    out.append(buf)
    return out


def _singing_need_s(
    text: str,
    *,
    target_cps_cjk: float = _SINGING_TARGET_CPS_CJK,
    target_cps_latin: float = _SINGING_TARGET_CPS_LATIN,
    min_hold_s: float = _SINGING_MIN_HOLD_S,
) -> float:
    n = max(_singing_lyric_len(text), 1)
    cps = float(target_cps_cjk) if _is_cjk_heavy(text) else float(target_cps_latin)
    need = n / max(0.5, cps)
    if n <= 8 and min_hold_s > 0:
        need = max(need, float(min_hold_s))
    return need


def defer_cue_starts_for_singing(
    cues: list[dict[str, Any]] | None,
    *,
    target_cps_cjk: float = _SINGING_TARGET_CPS_CJK,
    target_cps_latin: float = _SINGING_TARGET_CPS_LATIN,
    min_hold_s: float = _SINGING_MIN_HOLD_S,
    short_chars: int = _SINGING_MERGE_SHORT_CHARS,
) -> list[dict[str, Any]]:
    """Unstick flash-length complete lines blocked by an early next island.

    Only rewrites cues that are already XLSub-sized in text (>=8 chars) but still
    shorter than 1.5s because the next island starts within 0.65s. Broader shifting
    destroys later verse alignment, so this stays narrowly scoped.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    for i in range(len(ordered) - 1):
        cur = ordered[i]
        text = str(cur.get("text") or "").strip()
        start = float(cur.get("start") or 0)
        end = float(cur.get("end") or start)
        if _singing_lyric_len(text) < 8 or (end - start) >= 1.5:
            continue
        need = _singing_need_s(
            text,
            target_cps_cjk=target_cps_cjk,
            target_cps_latin=target_cps_latin,
            min_hold_s=min_hold_s,
        )
        nxt = ordered[i + 1]
        nxt_start = float(nxt.get("start") or 0)
        if nxt_start - end >= 0.65 or nxt_start >= start + need - 0.05:
            continue
        shift = min((start + need) - nxt_start, 5.0)
        if shift < 0.25:
            continue
        nxt_end = float(nxt.get("end") or nxt_start)
        dur = max(0.45, nxt_end - nxt_start)
        nxt["start"] = nxt_start + shift
        nxt["end"] = nxt["start"] + dur
        if i + 2 < len(ordered):
            fol = ordered[i + 2]
            fol_start = float(fol.get("start") or 0)
            need_gap = float(nxt["end"]) + 0.06
            if fol_start < need_gap:
                bump = min(need_gap - fol_start, 5.0)
                fol["start"] = fol_start + bump
                fol["end"] = float(fol.get("end") or fol_start) + bump
    return ordered


def stretch_cues_for_singing(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    target_cps_cjk: float = _SINGING_TARGET_CPS_CJK,
    target_cps_latin: float = _SINGING_TARGET_CPS_LATIN,
    max_cue_s: float = _SINGING_MAX_CUE_S,
    neighbor_gap_s: float = _SINGING_NEIGHBOR_GAP_S,
    min_hold_s: float = _SINGING_MIN_HOLD_S,
    drop_fillers: bool = True,
    defer_early_starts: bool = True,
) -> list[dict[str, Any]]:
    """Expand cue ends for sung / slow CJK phrases without wall-to-wall fill.

    Spoken-rate paint (~9 CPS) leaves karaoke lines flashing off mid-melisma.
    Grow each cue to a singing-rate duration (XLSub ~1.6–1.8 CPS), capped by the
    next lyric start — tight handoffs abut naturally; wide gaps do not steal the
    next line's intro (full-abut was polluting line-level scores).
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if drop_fillers:
        ordered = [
            c for c in ordered
            if not _SINGING_FILLER_RE.match(str(c.get("text") or "").strip())
        ]
    if not ordered:
        return []
    if defer_early_starts:
        ordered = defer_cue_starts_for_singing(
            ordered,
            target_cps_cjk=target_cps_cjk,
            target_cps_latin=target_cps_latin,
            min_hold_s=min_hold_s,
        )
    media_end = float(media_end_s) if media_end_s is not None and media_end_s > 0 else None
    gap = max(0.02, float(neighbor_gap_s))
    cap = max(1.0, float(max_cue_s))
    out: list[dict[str, Any]] = []
    for i, cue in enumerate(ordered):
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        if i + 1 < len(ordered):
            boundary = float(ordered[i + 1].get("start") or end) - gap
        elif media_end is not None:
            boundary = media_end - gap
        else:
            boundary = start + cap
        boundary = max(start + 0.25, boundary)
        need = _singing_need_s(
            text,
            target_cps_cjk=target_cps_cjk,
            target_cps_latin=target_cps_latin,
            min_hold_s=min_hold_s,
        )
        target_end = max(end, start + need)
        new_end = min(target_end, start + cap, boundary)
        new_end = max(new_end, start + 0.25)
        item = {**cue, "start": start, "end": new_end, "text": text}
        out.append(item)
    return _clamp_cue_overlaps(out)


def _cue_is_timestamp_collapsed(cue: dict[str, Any]) -> bool:
    text = str(cue.get("text") or "").strip()
    if not text:
        return False
    n = _display_len(text)
    if n < _COLLAPSE_MIN_CHARS:
        return False
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    dur = max(0.0, end - start)
    if dur <= 0.08:
        return True
    return (n / dur) > _COLLAPSE_CPS


def _repeated_call_units(text: str) -> tuple[int, str] | None:
    """
    Detect soft-AV name-call / stutter loops: 「風香、風香、風香」 or jammed
    「風香風香風香」. Returns (repeat_count, base) when ≥2 identical units.
    """
    raw = str(text or "").strip()
    if not raw:
        return None
    parts = [p.strip() for p in re.split(r"[、，,]+", raw) if p.strip()]
    if len(parts) >= 2:
        bases = [re.sub(r"[。．.！!？?\s]+$", "", p) for p in parts]
        bases = [b for b in bases if b]
        if len(bases) >= 2 and len(set(bases)) == 1:
            base = bases[0]
            # 2–4 char name / short react (風香 / うん / ねえ)
            if 1 <= _display_len(base) <= 4:
                return len(bases), base
    # Jammed identical CJK units without commas (風香風香風香).
    bare = re.sub(r"[、，,。．.！!？?\s]+", "", raw)
    if len(bare) < 4:
        return None
    for unit_len in (2, 3, 1, 4):
        if len(bare) % unit_len != 0:
            continue
        n = len(bare) // unit_len
        if n < 2:
            continue
        unit = bare[:unit_len]
        if unit * n == bare and _is_cjk_heavy(unit):
            return n, unit
    return None


def _acoustic_end_across_spans(
    spans: list[tuple[float, float]],
    *,
    anchor_s: float,
    boundary_s: float,
    max_hole_s: float = 0.85,
    max_peaks: int | None = None,
) -> float | None:
    """
    Extend from ``anchor_s`` across consecutive speech spans up to ``boundary_s``.

    Duration comes from measured RMS/VAD peaks — not reading-rate estimates.
    ``max_peaks`` caps how many peaks to cover (name-call loops: one peak per
    repeated unit). Soft-AV name breaths are often 0.5–0.7s, so ``max_hole_s``
    defaults above the old 0.55 paint bridge.
    """
    if not spans:
        return None
    boundary = float(boundary_s)
    anchor = float(anchor_s)
    if boundary <= anchor + 0.05:
        return None
    usable = [
        (float(a), float(b))
        for a, b in spans
        if float(b) > float(a) + 0.05
        and float(b) > anchor - 0.05
        and float(a) < boundary - 0.02
    ]
    if not usable:
        return None
    usable.sort(key=lambda p: p[0])
    # Start at the first span that overlaps / begins at the cue onset.
    start_i = 0
    for i, (a, b) in enumerate(usable):
        if b >= anchor - 0.02 and a <= anchor + 0.55:
            start_i = i
            break
        if a >= anchor - 0.02:
            start_i = i
            break
    end = max(anchor, float(usable[start_i][1]))
    peaks = 1
    selected: list[tuple[float, float]] = [
        (float(usable[start_i][0]), float(usable[start_i][1]))
    ]
    for a, b in usable[start_i + 1 :]:
        if float(a) >= boundary - 0.02:
            break
        if float(a) > end + float(max_hole_s):
            break
        if max_peaks is not None and peaks >= int(max_peaks):
            break
        selected.append((float(a), float(b)))
        end = max(end, float(b))
        peaks += 1
    # pcm merge_gap often glues later soft peaks into one fat span. When we
    # intentionally cover N name-call peaks, trim an oversized last peak to the
    # median duration of earlier peaks (DLDSS-553 3rd 「風香」).
    if max_peaks is not None and len(selected) >= 2:
        durs = [max(0.05, b - a) for a, b in selected]
        med = sum(durs[:-1]) / len(durs[:-1])
        if durs[-1] > max(1.15, med * 1.35):
            la, _lb = selected[-1]
            end = min(end, la + med)
    end = min(end, boundary - 0.04 if boundary - anchor > 0.2 else boundary)
    if end <= anchor + 0.08:
        return None
    return end


def _estimate_speech_duration_s(text: str, *, available_s: float) -> float:
    """Reading-rate duration for collapsed anime-whisper / Qwen TEN blobs.

    Never inflate past ``available_s`` — a 0.45s floor that ignored the next
    cue start produced overlapping flash cues on soft-AV Galgame TEN paths
    (JUR-854: many ≤80ms lines with CPS ≫40).

    Prefer measured speech spans (``extend_cues_to_speech_spans`` / paint grow)
    for real soft-AV timing; this estimate is only a CPS safety floor.
    """
    n = max(_display_len(text), 1)
    target = _REPAIR_TARGET_CPS_JA if _is_cjk_heavy(text) else _REPAIR_TARGET_CPS_LATIN
    needed = n / target
    min_dur = n / _REPAIR_MIN_CPS
    cap = max(0.05, min(float(available_s), _REPAIR_MAX_EXPAND_S))
    # Prefer ≥0.45s only when the slot actually allows it.
    floor = min(0.45, cap) if cap >= 0.25 else cap
    dur = max(min_dur, needed, floor)
    return min(dur, cap)


def _rfind_soft_clause_cut(buf: str) -> int:
    """Return cut index (end of left) near a JA clause boundary, or -1."""
    s = str(buf or "")
    if len(s) < 6:
        return -1
    for token in ("から", "たら", "では", "には", "とは", "って", "、", "，"):
        j = s.rfind(token)
        if j >= 4:
            return j + len(token)
    for ch in "でがをにものなよ":
        j = s.rfind(ch)
        if j >= 4:
            return j + 1
    return -1


def _split_cue_text_parts(text: str, *, max_chars: int) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [
        p.strip()
        for p in re.split(r"(?<=[。！？!?．.｡…])\s*", raw)
        if p and p.strip()
    ]
    if not parts:
        parts = [raw]
    # Further split long clauses without sentence enders.
    out: list[str] = []
    limit = max(8, int(max_chars))
    soft_gate = max(6, int(limit * 0.55))
    for part in parts:
        if _display_len(part) <= limit:
            out.append(part)
            continue
        buf = ""
        for i, ch in enumerate(part):
            buf += ch
            if _display_len(buf) >= soft_gate and ch in _CLAUSE_BREAK:
                out.append(buf.strip())
                buf = ""
                continue
            if _display_len(buf) < limit:
                continue
            # Hard limit: never orphan 「って／った」 onto the next part
            # (DLDSS-559: …作|ってみたの via char-cap dump).
            rest = part[i + 1 :]
            if (
                (ch == "っ" or rest.startswith(("って", "った", "ってる", "ちゃう")))
                and _display_len(buf) <= limit + 6
            ):
                continue
            soft = _rfind_soft_clause_cut(buf)
            if soft >= soft_gate:
                left = buf[:soft].strip()
                right = buf[soft:]
                if left:
                    out.append(left)
                buf = right
            else:
                out.append(buf.strip())
                buf = ""
        if buf.strip():
            out.append(buf.strip())
    return [p for p in out if p]


def _split_expanded_cue(
    cue: dict[str, Any],
    *,
    max_chars: int = _MAX_CJK_CHARS,
    part_gap_s: float = _REPAIR_PART_GAP_S,
) -> list[dict[str, Any]]:
    """
    Split a cue across its (already rate-estimated) span.

    Each part gets proportional time; the last part does NOT absorb leftover
    silence up to ``end`` (that caused 10–20s trailing cues).
    """
    text = str(cue.get("text") or "").strip()
    if not text:
        return []
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    if end <= start:
        end = start + 0.6
    parts = _split_cue_text_parts(text, max_chars=max_chars)
    meta = {
        k: v
        for k, v in cue.items()
        if k not in ("start", "end", "text", "words")
    }
    if len(parts) <= 1:
        item = {**meta, "start": start, "end": max(end, start + 0.35), "text": text}
        return [item]
    weights = [max(_display_len(p), 1) for p in parts]
    total_w = float(sum(weights)) or 1.0
    gap = max(0.0, float(part_gap_s))
    span = end - start
    usable = max(0.35 * len(parts), span - gap * (len(parts) - 1))
    t = start
    out: list[dict[str, Any]] = []
    for i, part_text in enumerate(parts):
        dur = usable * (weights[i] / total_w)
        # Cap individual parts so one clause cannot monopolize a chunk.
        dur = min(max(dur, 0.35), _MAX_CUE_DURATION_S)
        end_t = t + dur
        if i == len(parts) - 1:
            # Stay within parent end, but never stretch into silence.
            end_t = min(end_t, end)
        out.append({**meta, "start": t, "end": max(end_t, t + 0.35), "text": part_text})
        t = end_t + (gap if i < len(parts) - 1 else 0.0)
        if t >= end and i < len(parts) - 1:
            # Remaining parts: pack tightly at the end edge.
            t = min(t, end - 0.35 * (len(parts) - i - 1))
    return out


def _clamp_cue_overlaps(
    cues: list[dict[str, Any]] | None,
    *,
    min_gap_s: float = 0.02,
    min_dur_s: float = 0.05,
) -> list[dict[str, Any]]:
    """Pull overlapping ends back so each cue ends before the next start."""
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    gap = max(0.0, float(min_gap_s))
    floor = max(0.05, float(min_dur_s))
    for i in range(len(ordered) - 1):
        start_i = float(ordered[i].get("start") or 0)
        next_start = float(ordered[i + 1].get("start") or start_i)
        limit = next_start - gap
        end_i = float(ordered[i].get("end") or start_i)
        if end_i <= limit:
            continue
        if next_start <= start_i + 1e-3:
            ordered[i]["end"] = start_i + floor
        else:
            ordered[i]["end"] = max(start_i + floor, limit)
            if float(ordered[i]["end"]) > limit:
                ordered[i]["end"] = max(start_i + 0.05, limit)
    return ordered


def redistribute_overpacked_cue_runs(
    cues: list[dict[str, Any]] | None,
    *,
    pack_window_s: float = 0.20,
    media_end_s: float | None = None,
    max_part_chars: int = _MAX_CJK_CHARS,
) -> list[dict[str, Any]]:
    """
    Fix flash/overpacked soft-AV cues that share nearly the same start.

    Qwen Galgame TEN paints dialogue-turn chunks 1:1 onto tiny PCM RMS spans
    (or ForcedAligner word groups collapse). Result: 50–150ms cues with CPS≫40
    (JUR-854). Merge each near-duplicate-start run, expand by speaking rate into
    the gap before the next run, then split into readable parts.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []

    window = max(0.05, float(pack_window_s))
    runs: list[list[dict[str, Any]]] = [[ordered[0]]]
    for cue in ordered[1:]:
        if abs(float(cue.get("start") or 0) - float(runs[-1][0].get("start") or 0)) <= window:
            runs[-1].append(cue)
        else:
            runs.append([cue])

    out: list[dict[str, Any]] = []
    for i, run in enumerate(runs):
        start = min(float(c.get("start") or 0) for c in run)
        # Healthy single cues already carry measured speech-span ends from
        # paint/ForcedAligner. Replacing them with speaking-rate estimates
        # *shrinks* soft-AV tails (DLDSS-559: 「よかった」 13.0→12.5).
        if len(run) == 1 and not _cue_is_timestamp_collapsed(run[0]):
            out.append(dict(run[0]))
            continue
        if i + 1 < len(runs):
            boundary = float(runs[i + 1][0].get("start") or start)
            gap = 0.04
        elif media_end_s is not None and float(media_end_s) > start:
            boundary = float(media_end_s)
            gap = 0.0
        else:
            boundary = max(float(c.get("end") or start) for c in run) + 8.0
            gap = 0.0

        joined = "".join(str(c.get("text") or "") for c in run).strip()
        if not joined:
            continue
        available = max(0.05, boundary - start - gap)
        need = _estimate_speech_duration_s(joined, available_s=available)
        end = min(start + need, start + available)
        if available >= 0.35:
            end = max(end, start + min(0.35, available))

        # Single short reactive line: keep original duration when not collapsed.
        if len(run) == 1 and _display_len(joined) < 8:
            orig_end = float(run[0].get("end") or start)
            orig_dur = max(0.0, orig_end - start)
            if not _cue_is_timestamp_collapsed(run[0]):
                end = min(max(orig_end, start + min(0.25, available)), start + available)

        blob: dict[str, Any] = {"start": start, "end": end, "text": joined}
        meta = {
            k: v
            for k, v in run[0].items()
            if k not in ("start", "end", "text", "words")
        }
        blob.update(meta)

        should_split = (
            len(run) > 1
            or _display_len(joined) > max(8, int(max_part_chars))
            or (end - start) > _MAX_CUE_DURATION_S
        )
        if should_split:
            parts = _split_expanded_cue(blob, max_chars=max_part_chars)
            if not parts:
                out.append(blob)
                continue
            # Re-fit split parts into the hard slot [start, end].
            span = max(0.05, end - start)
            t0 = float(parts[0].get("start") or start)
            t1 = max(float(p.get("end") or t0) for p in parts)
            src = max(0.05, t1 - t0)
            clamped: list[dict[str, Any]] = []
            for j, part in enumerate(parts):
                ps = start + (float(part.get("start") or t0) - t0) / src * span
                if j == len(parts) - 1:
                    pe = end
                else:
                    pe = start + (float(part.get("end") or t0) - t0) / src * span
                item = {**part, "start": ps, "end": max(ps + 0.05, pe)}
                clamped.append(item)
            out.extend(_clamp_cue_overlaps(clamped, min_gap_s=0.02))
        else:
            out.append(blob)
    return _clamp_cue_overlaps(out)


def retime_dense_cue_clusters(
    cues: list[dict[str, Any]] | None,
    *,
    cluster_gap_s: float = 0.85,
    media_end_s: float | None = None,
    max_part_chars: int = _MAX_CJK_CHARS,
) -> list[dict[str, Any]]:
    """
    Re-pack cue clusters that sit within a short silence gap.

    After redistribute/repair, a long line may still be CPS-collapsed because the
    next cue starts too soon (JUR-854 @71s: 16-char question then そうです 0.36s
    later). Treat near-adjacent cues as one speech cluster, allocate speaking-
    rate budgets, and optionally borrow trailing silence until the next cluster.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []

    gap_lim = max(0.15, float(cluster_gap_s))
    clusters: list[list[dict[str, Any]]] = [[ordered[0]]]
    for cue in ordered[1:]:
        prev = clusters[-1][-1]
        prev_end = float(prev.get("end") or 0)
        cur_start = float(cue.get("start") or 0)
        # Same breath / rapid turn exchange
        if cur_start - prev_end <= gap_lim or cur_start - float(prev.get("start") or 0) <= gap_lim:
            clusters[-1].append(cue)
        else:
            clusters.append([cue])

    out: list[dict[str, Any]] = []
    for i, cluster in enumerate(clusters):
        # Only retime clusters that still look collapsed / overpacked.
        needs = False
        for c in cluster:
            if _cue_is_timestamp_collapsed(c):
                needs = True
                break
            d = float(c.get("end") or 0) - float(c.get("start") or 0)
            if d < 0.25 and _display_len(str(c.get("text") or "")) >= 8:
                needs = True
                break
        if len(cluster) >= 2:
            # Near-dup or flash pack even if individual CPS ok
            span = float(cluster[-1].get("end") or 0) - float(cluster[0].get("start") or 0)
            chars = sum(_display_len(str(c.get("text") or "")) for c in cluster)
            if span > 0 and chars / span > 28:
                needs = True
        if not needs:
            out.extend(cluster)
            continue

        start = float(cluster[0].get("start") or 0)
        if i + 1 < len(clusters):
            boundary = float(clusters[i + 1][0].get("start") or start)
            trail_gap = 0.06
        elif media_end_s is not None and float(media_end_s) > start:
            boundary = float(media_end_s)
            trail_gap = 0.0
        else:
            boundary = max(float(c.get("end") or start) for c in cluster) + 12.0
            trail_gap = 0.0

        weights = [max(_display_len(str(c.get("text") or "")), 1) for c in cluster]
        ideals = [
            _estimate_speech_duration_s(str(c.get("text") or ""), available_s=30.0)
            for c in cluster
        ]
        ideal_total = float(sum(ideals))
        available = max(0.15, boundary - start - trail_gap)
        # Prefer ideal speaking time; never exceed the next cluster.
        budget = min(ideal_total, available)
        # Ensure at least a readable floor when the slot allows.
        min_total = min(available, 0.35 * len(cluster))
        budget = max(budget, min_total)

        cursor = start
        part_gap = 0.04 if len(cluster) > 1 else 0.0
        usable = max(0.15, budget - part_gap * (len(cluster) - 1))
        total_w = float(sum(weights)) or 1.0
        for j, (cue, w) in enumerate(zip(cluster, weights)):
            if j == len(cluster) - 1:
                end = start + budget
            else:
                dur = usable * (float(w) / total_w)
                dur = max(0.25, min(dur, _MAX_CUE_DURATION_S))
                end = min(cursor + dur, start + budget - 0.25 * (len(cluster) - j - 1))
            item = {**cue, "start": cursor, "end": max(cursor + 0.05, end)}
            text = str(item.get("text") or "")
            dur = float(item["end"]) - float(item["start"])
            if _display_len(text) > max_part_chars or dur > _MAX_CUE_DURATION_S:
                parts = _split_expanded_cue(item, max_chars=max_part_chars)
                out.extend(parts)
                cursor = float(parts[-1]["end"]) if parts else float(item["end"])
            else:
                out.append(item)
                cursor = float(item["end"])
            cursor += part_gap if j < len(cluster) - 1 else 0.0

    return _clamp_cue_overlaps(out)


_JA_TURNISH_SPLIT_RE = re.compile(
    r"(?="
    # Fillers must start a turn — never match okurigana inside 会うんだっけ / 思うんだ.
    r"えー+|あー+|ええ+|(?<![ぁ-んァ-ン一-龥])ううん*|(?<![ぁ-んァ-ン一-龥])うん+(?![ぁ-ん])|"
    r"はぁ+|ふぅ*|"
    r"昨日|今日|明日|今度|実は|そういえば|どう？|どう\?|"
    r"お父さん|お母さん|先生が|(?<![てでがのにを])大変だ|"
    r"わぁ+|わあ+"
    r")"
)


_JA_CLAUSE_SPLIT_RE = re.compile(
    # Multi-mora clause ends only. Bare て/の/も/で and te-form+aux (行って|くる)
    # shredded single soft-AV turns into synthetic proportional stamps (FNS-258).
    r"(?<=から)|(?<=たら)|(?<=ては)|(?<=では)(?!ない)|(?<=には)|(?<=とは)"
    r"|(?<=だって)|(?<=ですって)"
    # Quotative …って|… but never te-form auxiliaries (作ってみた / 行ってくる).
    r"|(?<=[一-龥]って)(?!くる|き|いる|いた|いっ|る|た|て|しま|あげ|くれ|もら|"
    r"みる|みた|みて|ほし|おく|おき|ある|あっ|いく|おいで|ください|って)"
)


_JA_NAME_PREFIX_RE = re.compile(
    r"^(お父さん|お母さん|先生|紗枝子ちゃん|才子ちゃん|細子ちゃん)[、，,]?"
)


def _split_cue_at_index(
    cue: dict[str, Any],
    *,
    text: str,
    start: float,
    end: float,
    dur: float,
    cut: int,
) -> list[dict[str, Any]] | None:
    left = text[:cut].strip()
    right = text[cut:].strip()
    if len(left) < 2 or len(right) < 3:
        return None
    total = max(1, len(left) + len(right))
    mid = start + dur * (len(left) / total)
    mid = min(max(mid, start + 0.28), end - 0.28)
    return [
        {**cue, "start": start, "end": mid, "text": left},
        {**cue, "start": mid + 0.04, "end": end, "text": right},
    ]


def _best_mid_cut(text: str, pattern: re.Pattern[str]) -> int:
    mid_lo = max(2, int(len(text) * 0.22))
    mid_hi = min(len(text) - 3, int(len(text) * 0.78))
    best_i = -1
    best_dist = 10**9
    for m in pattern.finditer(text):
        i = m.start()
        if i < mid_lo or i > mid_hi:
            continue
        dist = abs(i - len(text) // 2)
        if dist < best_dist:
            best_dist = dist
            best_i = i
    return best_i


def _split_overlong_punct_cues(
    cues: list[dict[str, Any]] | None,
    *,
    max_dur_s: float = 2.15,
) -> list[dict[str, Any]]:
    """
    Split soft-AV cues that glue two phrases on one fat RMS span.

    Example (DLDSS-559): 「お父さん、勉強教えられないじゃん。」 on a 2.5s+
    island → two readable cues at the 、 boundary (char-proportional).
    Also splits ForcedAligner mega-cues that lack punctuation by turn-ish
    anchors (えー/昨日/お父さん…) or mid-clause particles.
    """
    if not cues:
        return []
    out: list[dict[str, Any]] = []
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        dur = max(0.0, end - start)
        if dur < float(max_dur_s) or len(text) < 8:
            out.append(dict(cue))
            continue
        # Keep soft-AV name-call loops intact (風香×3 is one turn, ~3s acoustic).
        if _repeated_call_units(text) is not None:
            out.append(dict(cue))
            continue

        split_pair: list[dict[str, Any]] | None = None

        # 0) Vocative / role name prefix (お父さん勉強… → お父さん | 勉強…)
        if dur >= 2.2:
            nm = _JA_NAME_PREFIX_RE.match(text)
            if nm and len(text) - nm.end() >= 4:
                split_pair = _split_cue_at_index(
                    cue, text=text, start=start, end=end, dur=dur, cut=nm.end()
                )

        # 1) Comma / enumeration — but keep single polite turns intact
        # (「私が、社長の、白井と申します」 is one self-intro, not two phrases).
        if split_pair is None:
            polite_one_turn = bool(
                re.search(r"(?:です|ます|ました|ません|申します)[。．.！!？?…]*$", text)
            )
            if not polite_one_turn:
                parts = [p for p in re.split(r"(?<=[、，,])", text) if p and p.strip()]
                if len(parts) >= 2:
                    left = parts[0].strip()
                    right = "".join(parts[1:]).strip()
                    connective = bool(
                        re.search(r"[がでて]、?$", left) and len(left) <= 12
                    )
                    if len(left) >= 2 and len(right) >= 4 and not connective:
                        split_pair = _split_cue_at_index(
                            cue, text=text, start=start, end=end, dur=dur, cut=len(left)
                        )

        # 2) Sentence-final mid-text (。！？)
        if split_pair is None:
            m = re.search(r"[。！？!?](?=.)", text)
            if m and 2 <= m.end() <= len(text) - 3:
                split_pair = _split_cue_at_index(
                    cue, text=text, start=start, end=end, dur=dur, cut=m.end()
                )

        # 3) Turn-ish anchors near the middle (ForcedAligner glue)
        if split_pair is None and dur >= float(max_dur_s):
            best_i = _best_mid_cut(text, _JA_TURNISH_SPLIT_RE)
            if best_i > 0:
                tail = text[best_i:]
                if re.match(r"えー+", tail) and re.search(
                    r"センチ|カップ|(?i)cm", tail
                ):
                    best_i = 0
            if best_i > 0:
                split_pair = _split_cue_at_index(
                    cue, text=text, start=start, end=end, dur=dur, cut=best_i
                )

        # 4) Soft clause particles near midpoint
        if split_pair is None and dur >= float(max_dur_s):
            best_i = _best_mid_cut(text, _JA_CLAUSE_SPLIT_RE)
            if best_i > 0:
                split_pair = _split_cue_at_index(
                    cue, text=text, start=start, end=end, dur=dur, cut=best_i
                )

        # 5) Last resort removed: CJK/char bisection produced mid-lexeme stamps
        # (FNS-258: 増えてるか分|かんないけど). Prefer leaving a long acoustic cue
        # intact over synthetic proportional halves.

        if split_pair:
            out.extend(split_pair)
        else:
            out.append(dict(cue))
    return out


def _clamp_overlong_cue_durations(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
) -> list[dict[str, Any]]:
    """
    Shrink cues whose span greatly exceeds speaking-rate need for the text.

    Fat Demucs/RMS islands often leave a short line (「昨日テレビで」) painted on
    a 1.5–2.5s span; MT then splits following lines into the leftover silence
    (DLDSS-559 cue3→4→5). Cap here so acoustic paint cannot donate that slack.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    for i, cue in enumerate(ordered):
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        dur = max(0.0, end - start)
        if dur < 0.9:
            continue
        if i + 1 < len(ordered):
            boundary = float(ordered[i + 1].get("start") or end)
            avail = max(0.28, boundary - start - 0.04)
        elif media_end_s is not None and float(media_end_s) > start:
            avail = max(0.28, float(media_end_s) - start)
        else:
            avail = dur
        need = _estimate_speech_duration_s(text, available_s=avail)
        # Never shrink name-call loops: acoustic cover of N peaks is authoritative
        # (DLDSS-553 「風香×3」 ~3s). Text-length soft_cap would crush them to ~1.4s.
        if _repeated_call_units(text) is not None:
            continue
        # Soft-AV mix: keep a little measured tail, but never donate a whole
        # second of silence/next-phrase energy to short lines (DLDSS-559).
        soft_cap = 1.45 if len(text) <= 10 else (2.35 if len(text) <= 20 else 3.2)
        soft_cap = max(soft_cap, need + 0.35)
        limit = min(avail, soft_cap, max(need * 1.45, need + 0.5, 0.55))
        if dur > limit + 0.08:
            cue["end"] = start + limit
    return ordered


def stretch_undersized_cue_timings(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
) -> list[dict[str, Any]]:
    """
    Stretch cues shorter than speaking-rate need when the next cue leaves room.

    ``repair_collapsed_asr_cues`` only fires at CPS≫40. Soft-AV paint often
    traps a normal 12–18 CPS line in a ~0.8–1.2s RMS blip while dialogue
    continues for another 1–2s with no subtitle (DLDSS-553). Expand ``end`` up
    to speaking-rate need without spilling into the next cue.

    Leave tight inter-cue breaths alone (DLDSS-559 healthy soft tails) — only
    stretch when there is a clear orphaned gap after the flash.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    for i, cue in enumerate(ordered):
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        dur = max(0.0, end - start)
        n = _display_len(text)
        if n < 4:
            continue
        if i + 1 < len(ordered):
            boundary = float(ordered[i + 1].get("start") or end)
            gap_after = max(0.0, boundary - end)
            # Keep a 40ms breath; do not eat intentional ~150ms soft-AV gaps.
            avail = max(0.05, boundary - start - 0.04)
        elif media_end_s is not None and float(media_end_s) > start:
            gap_after = max(0.0, float(media_end_s) - end)
            avail = max(0.05, float(media_end_s) - start)
        else:
            # No neighbor / media end: allow modest solo stretch only.
            gap_after = 99.0
            avail = max(dur, min(4.0, n / _REPAIR_TARGET_CPS_JA + 0.5))
        # Short intentional pauses between healthy cues must stay (0.15–0.35s).
        if gap_after < 0.45:
            continue
        need = _estimate_speech_duration_s(text, available_s=avail)
        if dur >= need * 0.88:
            continue
        # Require a real under-size (not a 50–100ms polish).
        if (need - dur) < 0.22 and (dur > 0 and n / dur < 14):
            continue
        if avail <= dur + 0.12:
            continue
        cue["end"] = start + min(need, avail)
    return ordered


def extend_cues_to_speech_spans(
    cues: list[dict[str, Any]] | None,
    speech_spans: list[tuple[float, float]] | None,
    *,
    media_end_s: float | None = None,
    max_hole_s: float = 0.85,
) -> list[dict[str, Any]]:
    """
    Stretch cue ends to measured speech peaks (not reading-rate estimates).

    Soft-AV name calls / soft tails often sit as consecutive RMS blips with
    0.5–0.7s breaths; paint that stopped at the first blip leaves dialogue
    with no subtitle (DLDSS-553 「風香、風香、風香」 ~3s acoustic / ~1s cue).
    """
    if not cues:
        return []
    spans = [
        (float(a), float(b))
        for a, b in (speech_spans or [])
        if float(b) > float(a) + 0.05
    ]
    if not spans:
        return [dict(c) for c in cues if isinstance(c, dict)]
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    for i, cue in enumerate(ordered):
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        if i + 1 < len(ordered):
            boundary = float(ordered[i + 1].get("start") or end)
        elif media_end_s is not None:
            boundary = float(media_end_s)
        else:
            boundary = end + 8.0
        if boundary <= end + 0.2:
            continue
        calls = _repeated_call_units(text)
        max_peaks = int(calls[0]) if calls is not None else None
        grown = _acoustic_end_across_spans(
            spans,
            anchor_s=start,
            boundary_s=boundary,
            max_hole_s=float(max_hole_s),
            max_peaks=max_peaks,
        )
        if grown is not None and grown > end + 0.12:
            cue["end"] = grown
    return ordered


def extend_cues_to_pcm_speech(
    cues: list[dict[str, Any]] | None,
    pcm: Any,
    sample_rate: int,
    *,
    media_end_s: float | None = None,
    max_hole_s: float = 0.85,
    merge_gap_s: float = 0.22,
) -> list[dict[str, Any]]:
    """Offline retime: probe PCM speech peaks and extend undersized cue ends."""
    from .speech_spans import pcm_speech_intervals

    if not cues:
        return []
    spans = pcm_speech_intervals(
        pcm,
        sample_rate,
        offset_s=0.0,
        merge_gap_s=float(merge_gap_s),
        min_speech_s=0.08,
    )
    return extend_cues_to_speech_spans(
        cues,
        spans,
        media_end_s=media_end_s,
        max_hole_s=max_hole_s,
    )


def ensure_readable_cue_timings(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    max_part_chars: int = _MAX_CJK_CHARS,
    stretch_to_reading_rate: bool = True,
) -> list[dict[str, Any]]:
    """
    Soft-AV / Galgame TEN safety net for ultra-short timestamps.

    1) Redistribute near-duplicate-start runs (PCM flicker / 1:1 short spans)
    2) Stretch remaining collapsed CPS blobs by speaking rate
    3) Stretch undersized (but not CPS-collapsed) lines into free gaps
    4) Re-pack dense clusters that still starve long lines
    5) Cap over-long short lines (fat RMS span donation)
    6) Drop junk flash cues / stretch residual sub-150ms clips
    7) Hard-clamp residual overlaps

    When ``stretch_to_reading_rate`` is False (ForcedAligner / TEN·FireRed
    acoustic stamps), skip speaking-rate redistribute / collapse-repair /
    stretch / dense retime **and** skip ``_clamp_overlong_cue_durations`` so
    measured PCM / aligner ends are not shrunk to reading-rate soft_cap.
    Still splits mega-cues, drops junk flashes, and clamps overlaps.
    """
    if not cues:
        return []
    if stretch_to_reading_rate:
        step = redistribute_overpacked_cue_runs(
            cues,
            media_end_s=media_end_s,
            max_part_chars=max_part_chars,
        )
        step = repair_collapsed_asr_cues(
            step,
            media_end_s=media_end_s,
            max_part_chars=max_part_chars,
        )
        step = stretch_undersized_cue_timings(step, media_end_s=media_end_s)
        step = retime_dense_cue_clusters(
            step,
            media_end_s=media_end_s,
            max_part_chars=max_part_chars,
        )
    else:
        step = [dict(c) for c in cues if isinstance(c, dict)]
    # ForcedAligner / soft-AV glue can need 2–3 split passes (mega → halves → phrases).
    for _ in range(3):
        before_n = len(step)
        step = _split_overlong_punct_cues(step)
        if len(step) == before_n:
            break
    if stretch_to_reading_rate:
        # Soft-AV fat-RMS donation guard (DLDSS-559). Acoustic paths omit this —
        # soft_cap was pulling TEN/FireRed ends earlier than spoken audio.
        step = _clamp_overlong_cue_durations(step, media_end_s=media_end_s)
        # Cap may shrink a line that still has free gap after — stretch once more.
        step = stretch_undersized_cue_timings(step, media_end_s=media_end_s)
    step = _drop_or_stretch_flash_cues(step, media_end_s=media_end_s)
    return _clamp_cue_overlaps(step)


_JUNK_FLASH_TEXT_RE = re.compile(
    r"^[\s\?？!！.。…‥・ー\-–—~～♪★☆♡♥❤゛゜]+$"
)


def _drop_or_stretch_flash_cues(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    min_readable_s: float = 0.2,
) -> list[dict[str, Any]]:
    """
    Soft-AV flash cleanup: drop punctuation-only blips; stretch leftover
    sub-150ms cues to a readable floor when the next cue leaves room.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    kept: list[dict[str, Any]] = []
    floor = max(0.15, float(min_readable_s))
    for i, cue in enumerate(ordered):
        text = str(cue.get("text") or "").strip()
        start = float(cue.get("start") or 0)
        end = float(cue.get("end") or start)
        dur = max(0.0, end - start)
        if dur < 0.15 and _JUNK_FLASH_TEXT_RE.match(text):
            continue
        if dur < 0.15:
            if i + 1 < len(ordered):
                boundary = float(ordered[i + 1].get("start") or end)
            elif media_end_s is not None and float(media_end_s) > start:
                boundary = float(media_end_s)
            else:
                boundary = start + floor
            avail = max(0.05, boundary - start - 0.02)
            cue["end"] = start + min(floor, avail)
            if float(cue["end"]) <= start + 0.05 and _JUNK_FLASH_TEXT_RE.match(text):
                continue
        kept.append(cue)
    return kept


def repair_collapsed_asr_cues(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    max_part_chars: int = _MAX_CJK_CHARS,
) -> list[dict[str, Any]]:
    """
    Stretch anime-whisper collapsed timestamps by speaking rate, then split.

    Without this, each ~30s of speech becomes a 0.3–0.9s cue; soft-AV CPS
    filtering treats that as hallucination and deletes the dialogue.

    Expansion uses char/CPS estimates and stops early — filling until the next
    cue start produced wall-to-wall subtitles with no silence gaps.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    n = len(ordered)
    for i, cue in enumerate(ordered):
        if not _cue_is_timestamp_collapsed(cue):
            continue
        start = float(cue.get("start") or 0)
        if i + 1 < n:
            boundary = float(ordered[i + 1].get("start") or start)
            gap = 0.04
        elif media_end_s is not None and float(media_end_s) > start:
            boundary = float(media_end_s)
            gap = 0.0
        else:
            boundary = start + _DEFAULT_CHUNK_SPAN_S
            gap = 0.0
        available = max(0.05, boundary - start - gap)
        text = str(cue.get("text") or "")
        cue["end"] = start + _estimate_speech_duration_s(text, available_s=available)
        # Hard clamp — estimate must never spill into the next cue.
        if i + 1 < n:
            cue["end"] = min(float(cue["end"]), boundary - gap)
            if float(cue["end"]) <= start:
                cue["end"] = start + min(0.2, max(0.05, available))
    out: list[dict[str, Any]] = []
    for cue in ordered:
        text = str(cue.get("text") or "")
        dur = float(cue.get("end") or 0) - float(cue.get("start") or 0)
        if _display_len(text) > max_part_chars or dur > _MAX_CUE_DURATION_S:
            out.extend(_split_expanded_cue(cue, max_chars=max_part_chars))
        else:
            out.append(cue)
    return _clamp_cue_overlaps(out)


def retime_wall_to_wall_cues(
    cues: list[dict[str, Any]] | None,
    *,
    target_cps: float | None = None,
    min_cps: float = _REPAIR_MIN_CPS,
    part_gap_s: float = _REPAIR_PART_GAP_S,
    run_gap_s: float = _REPAIR_RUN_GAP_S,
) -> list[dict[str, Any]]:
    """
    Shrink over-long cues in place to speaking-rate durations.

    Used to fix SRTs from an earlier repair that filled silence between
    anime-whisper 30s decode steps. Each cue keeps its start (rough timeline
    anchor); only ``end`` is pulled in so later cues stay sync'd to audio.
    Packing a whole touching-run to the run start would desync mid/late lines.
    """
    del run_gap_s  # kept for call-site compat; in-place shrink needs no runs
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    gap = max(0.0, float(part_gap_s))
    out: list[dict[str, Any]] = []
    for i, cue in enumerate(ordered):
        item = dict(cue)
        text = str(item.get("text") or "")
        start = float(item.get("start") or 0)
        end = float(item.get("end") or start)
        n = max(_display_len(text), 1)
        tgt = float(
            target_cps
            if target_cps is not None
            else (
                _REPAIR_TARGET_CPS_JA
                if _is_cjk_heavy(text)
                else _REPAIR_TARGET_CPS_LATIN
            )
        )
        need = max(n / max(float(min_cps), 1.0), n / tgt, 0.45)
        need = min(need, _MAX_CUE_DURATION_S)
        new_end = start + need
        # Never spill into the next cue's start (near-duplicate starts → tiny slot).
        if i + 1 < len(ordered):
            next_start = float(ordered[i + 1].get("start") or start)
            if next_start > start + 1e-3:
                slot = next_start - start
                cap = next_start - min(gap, max(0.0, slot * 0.25))
                new_end = min(new_end, cap)
                if new_end <= start:
                    new_end = start + min(0.2, slot * 0.5)
        # Only shrink (do not extend short accurate cues).
        if end > start + 0.05:
            item["end"] = min(end, max(new_end, start + 0.05))
        else:
            item["end"] = max(new_end, start + 0.35)
        if item["end"] <= start:
            item["end"] = start + 0.05
        out.append(item)
    # Final pass: hard-clamp any residual overlaps from near-duplicate starts.
    for i in range(len(out) - 1):
        start_i = float(out[i]["start"])
        next_start = float(out[i + 1]["start"])
        if next_start <= start_i + 1e-3:
            out[i]["end"] = min(float(out[i]["end"]), start_i + 0.05)
            continue
        limit = next_start - gap
        if float(out[i]["end"]) > limit:
            out[i]["end"] = max(start_i + 0.05, limit)
    return out
